/* eslint-disable react/require-default-props */
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

import {
  useTransformContext,
  useTransformEffect,
  useTransformInit,
} from "hooks";
import { useResize } from "./use-resize.hook";
import { boundLimiter } from "core/bounds/bounds.utils";

export type MiniMapProps = {
  children: React.ReactNode;
  width?: number;
  height?: number;
  borderColor?: string;
  /** Merged onto the viewport indicator (`.rzpp-minimap-preview`). */
  previewStyle?: React.CSSProperties;
  /** Extra class name(s) appended to `.rzpp-minimap-wrapper`. */
  wrapperClassName?: string;
  /** Extra class name(s) appended to `.rzpp-minimap-preview`. */
  previewClassName?: string;
  panning?: boolean;
} & React.DetailedHTMLProps<
  React.HTMLAttributes<HTMLDivElement>,
  HTMLDivElement
>;

const previewStyles = {
  position: "absolute",
  zIndex: 2,
  top: "0px",
  left: "0px",
  boxSizing: "border-box",
  border: "3px solid red",
  transformOrigin: "0% 0%",
  boxShadow: "rgba(0,0,0,0.2) 0 0 0 10000000px",
  pointerEvents: "none",
} as const;

export const MiniMap: React.FC<MiniMapProps> = ({
  width = 200,
  height = 200,
  borderColor = "red",
  previewStyle,
  wrapperClassName,
  previewClassName,
  children,
  panning = true,
  ...rest
}) => {
  const [initialized, setInitialized] = useState(false);
  const instance = useTransformContext();
  const [isDown, setIsDown] = useState(false);

  const mainRef = useRef<HTMLDivElement | null>(null);
  const wrapperRef = useRef<HTMLDivElement | null>(null);
  const previewRef = useRef<HTMLDivElement | null>(null);

  const getViewportSize = useCallback(() => {
    if (instance.wrapperComponent) {
      const rect = instance.wrapperComponent.getBoundingClientRect();

      return {
        width: rect.width,
        height: rect.height,
      };
    }
    return {
      width: 0,
      height: 0,
    };
  }, [instance.wrapperComponent]);

  const getContentSize = useCallback(() => {
    if (instance.contentComponent) {
      const rect = instance.contentComponent.getBoundingClientRect();

      return {
        width: rect.width / instance.state.scale,
        height: rect.height / instance.state.scale,
      };
    }
    return {
      width: 0,
      height: 0,
    };
  }, [instance.contentComponent, instance.state.scale]);

  const computeMiniMapScale = useCallback(() => {
    const contentSize = getContentSize();
    const scaleX = width / contentSize.width;
    const scaleY = height / contentSize.height;
    const scale = scaleY > scaleX ? scaleX : scaleY;

    return scale;
  }, [getContentSize, height, width]);

  const computeMiniMapSize = () => {
    const contentSize = getContentSize();
    const scaleX = width / contentSize.width;
    const scaleY = height / contentSize.height;
    if (scaleY > scaleX) {
      return { width, height: contentSize.height * scaleX };
    }
    return { width: contentSize.width * scaleY, height };
  };

  const computeMiniMapStyle = () => {
    const scale = computeMiniMapScale();
    const style = {
      transform: `scale(${scale || 1})`,
      transformOrigin: "0% 0%",
      position: "absolute",
      boxSizing: "border-box",
      zIndex: 1,
      // overflow: "hidden",
    } as const;

    if (wrapperRef.current) {
      const el = wrapperRef.current.style;
      el.transform = style.transform;
      el.transformOrigin = style.transformOrigin;
      el.position = style.position;
      el.boxSizing = style.boxSizing;
      el.zIndex = String(style.zIndex);
    }
  };

  const transformMiniMap = () => {
    computeMiniMapStyle();
    const miniSize = computeMiniMapSize();
    const wrapSize = getContentSize();
    if (wrapperRef.current) {
      wrapperRef.current.style.width = `${wrapSize.width}px`;
      wrapperRef.current.style.height = `${wrapSize.height}px`;
    }
    if (mainRef.current) {
      mainRef.current.style.width = `${miniSize.width}px`;
      mainRef.current.style.height = `${miniSize.height}px`;
    }
    if (previewRef.current) {
      const size = getViewportSize();
      const scale = computeMiniMapScale();
      const previewScale = scale * (1 / instance.state.scale);
      const transform = instance.handleTransformStyles(
        -instance.state.positionX * previewScale,
        -instance.state.positionY * previewScale,
        1,
      );

      previewRef.current.style.transform = transform;
      previewRef.current.style.width = `${size.width * previewScale}px`;
      previewRef.current.style.height = `${size.height * previewScale}px`;
    }
  };

  const initialize = () => {
    transformMiniMap();
  };

  useTransformEffect(() => {
    transformMiniMap();
  });

  useTransformInit(() => {
    initialize();
    setInitialized(true);
  });

  useResize(instance.contentComponent, initialize, [initialized]);

  useEffect(() => {
    const move = (e: MouseEvent) => {
      if (
        panning &&
        isDown &&
        instance.contentComponent &&
        previewRef.current &&
        mainRef.current
      ) {
        const scale = computeMiniMapScale();
        const previewRect = previewRef.current.getBoundingClientRect();
        const mainRect = mainRef.current.getBoundingClientRect();

        const relativeX = (e.clientX - mainRect.left) / scale;
        const relativeY = (e.clientY - mainRect.top) / scale;

        const x = relativeX - previewRect.width / 2;
        const y = relativeY - previewRect.height / 2;

        const instanceWidth =
          (instance.wrapperComponent?.offsetWidth || 0) * instance.state.scale;
        const instanceHeight =
          (instance.wrapperComponent?.offsetHeight || 0) * instance.state.scale;

        const limitWidth =
          instanceWidth - previewRect.width * 2 * instance.state.scale;
        const limitHeight =
          instanceHeight - previewRect.height * 2 * instance.state.scale;

        const boundedX = boundLimiter(
          x * instance.state.scale,
          0,
          limitWidth,
          true,
        );

        const boundedY = boundLimiter(
          y * instance.state.scale,
          0,
          limitHeight,
          true,
        );

        instance.setState(instance.state.scale, -boundedX, -boundedY);
      }
    };

    const setDown = (e: MouseEvent) => {
      if (
        mainRef.current?.contains(e.target as Node) ||
        e.target === mainRef.current
      ) {
        move(e);
        setIsDown(true);
      }
    };
    const setUp = () => {
      setIsDown(false);
    };
    // Listen on the mini map's own document so it keeps working inside
    // portal windows and iframes.
    const doc = mainRef.current?.ownerDocument ?? document;
    doc.addEventListener("mousedown", setDown);
    doc.addEventListener("mouseup", setUp);
    doc.addEventListener("mousemove", move);
    return () => {
      doc.removeEventListener("mousedown", setDown);
      doc.removeEventListener("mousemove", move);
      doc.removeEventListener("mouseup", setUp);
    };
  }, [computeMiniMapScale, instance, isDown, panning]);

  const wrapperStyle = useMemo(() => {
    return {
      position: "relative",
      zIndex: 2,
      // overflow: "hidden",
      userSelect: "none",
    } as const;
  }, []);

  return (
    <div
      {...rest}
      ref={mainRef}
      style={wrapperStyle}
      className={`rzpp-mini-map ${rest.className || ""}`.trim()}
    >
      <div
        style={{ pointerEvents: "none" }}
        ref={wrapperRef}
        className={`rzpp-minimap-wrapper ${wrapperClassName || ""}`.trim()}
      >
        {children}
      </div>
      <div
        className={`rzpp-minimap-preview ${previewClassName || ""}`.trim()}
        ref={previewRef}
        style={{ ...previewStyles, borderColor, ...previewStyle }}
      />
    </div>
  );
};
